import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const PERIOD_PATTERN = /^\d{4}-(0[1-9]|1[0-2])$/;

function fail(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') {
    return Number.isFinite(v);
  }
  if (typeof v === 'string') {
    return v.trim() !== '' && Number.isFinite(Number(v));
  }
  return false;
}

function isId(v: unknown): boolean {
  return isNumeric(v) && Number.isInteger(Number(v)) && Number(v) > 0;
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

@Controller('api/v1')
export class FnSfr01001Controller {
  @Get('/closing-data')
  async listClosingData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const closingPeriod = query['closingPeriod'];
    const accountingUnitId = query['accountingUnitId'];
    if (typeof closingPeriod !== 'string' || !PERIOD_PATTERN.test(closingPeriod)) {
      throw fail('결산 기간을 YYYY-MM 형식으로 입력해 주세요.');
    }
    if (!isId(accountingUnitId)) {
      throw fail('회계단위를 선택해 주세요.');
    }
    const pageRaw = isBlank(query['page']) ? 0 : Number(query['page']);
    const sizeRaw = isBlank(query['size']) ? 20 : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw fail('쪽 번호와 쪽 크기가 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const params = {
        closingPeriod,
        accountingUnitId: String(accountingUnitId),
        limit: size,
        offset: page * size,
      };
      const items = await db.query(
        `SELECT closing_data_id AS "closingDataId",
                closing_period AS "closingPeriod",
                accounting_unit_id AS "accountingUnitId",
                account_subject_id AS "accountSubjectId",
                project_id AS "projectId",
                department_id AS "departmentId",
                closing_amount AS "closingAmount"
           FROM closing_data
          WHERE closing_period = :closingPeriod
            AND accounting_unit_id = CAST(:accountingUnitId AS bigint)
          ORDER BY closing_data_id
          LIMIT :limit OFFSET :offset`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM closing_data
          WHERE closing_period = :closingPeriod
            AND accounting_unit_id = CAST(:accountingUnitId AS bigint)`,
        { closingPeriod, accountingUnitId: String(accountingUnitId) },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/closing-data')
  @HttpCode(200)
  async createClosingData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const closingPeriod = data['closingPeriod'];
    if (typeof closingPeriod !== 'string' || !PERIOD_PATTERN.test(closingPeriod)) {
      throw fail('결산 기간을 YYYY-MM 형식으로 입력해 주세요.');
    }
    if (!isId(data['accountingUnitId'])) {
      throw fail('회계단위를 선택해 주세요.');
    }
    if (!isId(data['accountSubjectId'])) {
      throw fail('계정과목을 선택해 주세요.');
    }
    if (!isBlank(data['projectId']) && !isId(data['projectId'])) {
      throw fail('프로젝트가 올바르지 않습니다.');
    }
    if (!isBlank(data['departmentId']) && !isId(data['departmentId'])) {
      throw fail('부서가 올바르지 않습니다.');
    }
    if (!isNumeric(data['closingAmount'])) {
      throw fail('결산 금액을 숫자로 입력해 주세요.');
    }
    const params = {
      closingPeriod,
      accountingUnitId: String(data['accountingUnitId']),
      accountSubjectId: String(data['accountSubjectId']),
      projectId: isBlank(data['projectId']) ? null : String(data['projectId']),
      departmentId: isBlank(data['departmentId']) ? null : String(data['departmentId']),
      closingAmount: String(data['closingAmount']),
    };
    return transaction(async (db) => {
      const units = await db.query(
        'SELECT accounting_unit_id FROM accounting_unit WHERE accounting_unit_id = CAST(:id AS bigint)',
        { id: params.accountingUnitId },
      );
      if (units.length === 0) {
        throw fail('존재하지 않는 회계단위입니다.');
      }
      const subjects = await db.query(
        'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:id AS bigint)',
        { id: params.accountSubjectId },
      );
      if (subjects.length === 0) {
        throw fail('존재하지 않는 계정과목입니다.');
      }
      if (params.projectId !== null) {
        const projects = await db.query(
          'SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)',
          { id: params.projectId },
        );
        if (projects.length === 0) {
          throw fail('존재하지 않는 프로젝트입니다.');
        }
      }
      if (params.departmentId !== null) {
        const departments = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
          { id: params.departmentId },
        );
        if (departments.length === 0) {
          throw fail('존재하지 않는 부서입니다.');
        }
      }
      // TODO: 마감된 기간 확인(422 CLOSING_PERIOD_CLOSED)은 마감 상태의 출처가 없어 구현하지 못했다.
      const rows = await db.query(
        `INSERT INTO closing_data
           (accounting_unit_id, account_subject_id, project_id, department_id,
            closing_period, closing_amount, created_at, updated_at)
         VALUES
           (CAST(:accountingUnitId AS bigint), CAST(:accountSubjectId AS bigint),
            CAST(:projectId AS bigint), CAST(:departmentId AS bigint),
            :closingPeriod, CAST(:closingAmount AS numeric), now(), now())
         RETURNING closing_data_id AS "closingDataId"`,
        params,
      );
      return { closingDataId: Number(rows[0]['closingDataId']) };
    });
  }

  @Patch('/closing-data/:closingDataId')
  async updateClosingData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['closingDataId'];
    if (!isId(idText)) {
      throw fail('결산자료 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const sets: string[] = [];
    const params: Record<string, unknown> = { closingDataId: idText };
    if ('accountSubjectId' in data) {
      if (!isId(data['accountSubjectId'])) {
        throw fail('계정과목이 올바르지 않습니다.');
      }
      sets.push('account_subject_id = CAST(:accountSubjectId AS bigint)');
      params['accountSubjectId'] = String(data['accountSubjectId']);
    }
    if ('projectId' in data) {
      if (!isBlank(data['projectId']) && !isId(data['projectId'])) {
        throw fail('프로젝트가 올바르지 않습니다.');
      }
      sets.push('project_id = CAST(:projectId AS bigint)');
      params['projectId'] = isBlank(data['projectId']) ? null : String(data['projectId']);
    }
    if ('departmentId' in data) {
      if (!isBlank(data['departmentId']) && !isId(data['departmentId'])) {
        throw fail('부서가 올바르지 않습니다.');
      }
      sets.push('department_id = CAST(:departmentId AS bigint)');
      params['departmentId'] = isBlank(data['departmentId']) ? null : String(data['departmentId']);
    }
    if ('closingAmount' in data) {
      if (!isNumeric(data['closingAmount'])) {
        throw fail('결산 금액을 숫자로 입력해 주세요.');
      }
      sets.push('closing_amount = CAST(:closingAmount AS numeric)');
      params['closingAmount'] = String(data['closingAmount']);
    }
    if (sets.length === 0) {
      throw fail('수정할 값을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closing_data_id FROM closing_data WHERE closing_data_id = CAST(:closingDataId AS bigint)',
        { closingDataId: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CLOSING_DATA_NOT_FOUND', '대상 결산자료를 찾을 수 없습니다.');
      }
      if (params['accountSubjectId'] !== undefined) {
        const subjects = await db.query(
          'SELECT account_subject_id FROM account_subject WHERE account_subject_id = CAST(:id AS bigint)',
          { id: params['accountSubjectId'] },
        );
        if (subjects.length === 0) {
          throw fail('존재하지 않는 계정과목입니다.');
        }
      }
      if (params['projectId'] !== undefined && params['projectId'] !== null) {
        const projects = await db.query(
          'SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)',
          { id: params['projectId'] },
        );
        if (projects.length === 0) {
          throw fail('존재하지 않는 프로젝트입니다.');
        }
      }
      if (params['departmentId'] !== undefined && params['departmentId'] !== null) {
        const departments = await db.query(
          'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
          { id: params['departmentId'] },
        );
        if (departments.length === 0) {
          throw fail('존재하지 않는 부서입니다.');
        }
      }
      // TODO: 마감된 기간 확인(409 CLOSING_PERIOD_CLOSED)은 마감 상태의 출처가 없어 구현하지 못했다.
      await db.execute(
        `UPDATE closing_data SET ${sets.join(', ')}, updated_at = now() WHERE closing_data_id = CAST(:closingDataId AS bigint)`,
        params,
      );
      return { closingDataId: Number(idText) };
    });
  }

  @Delete('/closing-data/:closingDataId')
  async deleteClosingData(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const idText = req.params['closingDataId'];
    if (!isId(idText)) {
      throw fail('결산자료 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT closing_data_id FROM closing_data WHERE closing_data_id = CAST(:closingDataId AS bigint)',
        { closingDataId: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'CLOSING_DATA_NOT_FOUND', '대상 결산자료를 찾을 수 없습니다.');
      }
      // TODO: 마감된 기간 확인(409 CLOSING_PERIOD_CLOSED)은 마감 상태의 출처가 없어 구현하지 못했다.
      await db.execute(
        'DELETE FROM closing_data WHERE closing_data_id = CAST(:closingDataId AS bigint)',
        { closingDataId: idText },
      );
      return {};
    });
  }
}

response.page:
import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

type Panel =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row };

export default function FnSfr01001Page({ role, notify }: PageProps) {
  const [period, setPeriod] = useState('');
  const [unitId, setUnitId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ period: string; unitId: number | string } | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [panel, setPanel] = useState<Panel | null>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, loading, reload } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/closing-data', role, undefined, {
      closingPeriod: applied.period,
      accountingUnitId: applied.unitId,
      page: pageNo,
    });
  }, [applied, pageNo, role]);

  function search() {
    if (period.trim() === '' || unitId === '') {
      notify('결산 기간과 회계단위를 선택해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ period: period.trim(), unitId });
  }

  function reset() {
    setPeriod('');
    setUnitId('');
    setApplied(null);
    setPageNo(0);
  }

  function openCreate() {
    setForm({
      closingPeriod: applied ? applied.period : period,
      accountingUnitId: applied ? applied.unitId : unitId,
      accountSubjectId: '',
      projectId: '',
      departmentId: '',
      closingAmount: '',
    });
    setPanel({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setForm({
      accountSubjectId: row.accountSubjectId ?? '',
      projectId: row.projectId ?? '',
      departmentId: row.departmentId ?? '',
      closingAmount: row.closingAmount ?? '',
    });
    setPanel({ kind: 'edit', row });
  }

  function setField(key: string, value: unknown) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  function close() {
    setPanel(null);
  }

  async function submitCreate() {
    const missing: string[] = [];
    if (!form.closingPeriod) missing.push('결산 기간');
    if (!form.accountingUnitId) missing.push('회계단위');
    if (!form.accountSubjectId) missing.push('계정과목');
    if (form.closingAmount === '' || form.closingAmount === undefined) missing.push('결산 금액');
    if (missing.length > 0) {
      throw new Error(missing.join(', ') + ' 항목을 입력해 주세요.');
    }
    const body: Row = {
      closingPeriod: form.closingPeriod,
      accountingUnitId: form.accountingUnitId,
      accountSubjectId: form.accountSubjectId,
      closingAmount: form.closingAmount,
    };
    if (form.projectId !== '') body.projectId = form.projectId;
    if (form.departmentId !== '') body.departmentId = form.departmentId;
    await call('POST', '/closing-data', role, body);
    notify('결산자료를 등록했습니다.');
    close();
    reload();
  }

  async function submitEdit(row: Row) {
    if (!form.accountSubjectId) {
      throw new Error('계정과목을 선택해 주세요.');
    }
    if (form.closingAmount === '' || form.closingAmount === undefined) {
      throw new Error('결산 금액을 입력해 주세요.');
    }
    const body: Row = {
      accountSubjectId: form.accountSubjectId,
      projectId: form.projectId === '' ? null : form.projectId,
      departmentId: form.departmentId === '' ? null : form.departmentId,
      closingAmount: form.closingAmount,
    };
    await call('PATCH', '/closing-data/' + String(row.closingDataId), role, body);
    notify('결산자료를 수정했습니다.');
    close();
    reload();
  }

  async function submitDelete(row: Row) {
    await call('DELETE', '/closing-data/' + String(row.closingDataId), role);
    notify('결산자료를 삭제했습니다.');
    close();
    reload();
  }

  const detailFields = (
    <>
      <Field label="계정과목" required>
        <LookupSelect
          table="account_subject"
          role={role}
          value={form.accountSubjectId}
          onChange={(v) => setField('accountSubjectId', v)}
        />
      </Field>
      <Field label="프로젝트">
        <LookupSelect
          table="project"
          role={role}
          value={form.projectId}
          onChange={(v) => setField('projectId', v)}
          placeholder="선택 안 함"
        />
      </Field>
      <Field label="부서">
        <LookupSelect
          table="department"
          role={role}
          value={form.departmentId}
          onChange={(v) => setField('departmentId', v)}
          placeholder="선택 안 함"
        />
      </Field>
      <Field label="결산 금액" required>
        <NumberInput value={form.closingAmount} onChange={(v) => setField('closingAmount', v)} />
      </Field>
    </>
  );

  return (
    <div className="doc">
      <section className="box">
        <h2>결산자료</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="결산 기간" required hint="YYYY-MM 형식">
            <TextInput value={period} onChange={setPeriod} placeholder="2025-01" />
          </Field>
          <Field label="회계단위" required>
            <LookupSelect table="accounting_unit" role={role} value={unitId} onChange={setUnitId} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={openCreate}>결산자료 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'closingPeriod', label: '결산 기간' },
            {
              key: 'accountSubjectId',
              label: '계정과목',
              render: (r) => <RefName table="account_subject" role={role} value={r.accountSubjectId} />,
            },
            {
              key: 'projectId',
              label: '프로젝트·부서',
              render: (r) => (
                <>
                  {r.projectId ? <RefName table="project" role={role} value={r.projectId} /> : '-'}
                  {' / '}
                  {r.departmentId ? <RefName table="department" role={role} value={r.departmentId} /> : '-'}
                </>
              ),
            },
            {
              key: 'closingAmount',
              label: '결산 금액',
              render: (r) => <Num value={r.closingAmount} />,
            },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <>
                  <button
                    className="ghost"
                    onClick={(e) => {
                      e.stopPropagation();
                      openEdit(r);
                    }}
                  >
                    수정
                  </button>
                  <button
                    className="ghost"
                    onClick={(e) => {
                      e.stopPropagation();
                      setPanel({ kind: 'delete', row: r });
                    }}
                  >
                    삭제
                  </button>
                </>
              ),
            },
          ]}
          rows={data ? data.items : []}
          empty={
            applied
              ? '해당 기간의 결산자료가 없습니다. 결산자료 등록 버튼으로 추가해 주세요.'
              : '결산 기간과 회계단위를 선택한 뒤 조회해 주세요.'
          }
        />
        {loading ? <p>불러오는 중입니다.</p> : null}
        <Pager
          page={data ? data.page : 0}
          size={data ? data.size : 20}
          total={data ? data.total : 0}
          onPage={setPageNo}
        />
      </section>

      {panel && panel.kind === 'create' ? (
        <Drawer title="결산자료 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="결산 기간" required hint="YYYY-MM 형식">
              <TextInput value={form.closingPeriod} onChange={(v) => setField('closingPeriod', v)} />
            </Field>
            <Field label="회계단위" required>
              <LookupSelect
                table="accounting_unit"
                role={role}
                value={form.accountingUnitId}
                onChange={(v) => setField('accountingUnitId', v)}
              />
            </Field>
            {detailFields}
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.kind === 'edit' ? (
        <Drawer title="결산자료 수정" onClose={close}>
          <Form onSubmit={() => submitEdit(panel.row)} submit="수정">
            {detailFields}
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.kind === 'delete' ? (
        <Drawer title="결산자료 삭제" onClose={close}>
          <Form
            onSubmit={() => submitDelete(panel.row)}
            submit="삭제"
            danger
            note="삭제한 결산자료는 되돌릴 수 없습니다. 계속하려면 삭제를 누르세요."
          >
            <p>
              {String(panel.row.closingPeriod)} 결산자료의 금액 <Num value={panel.row.closingAmount} />원을 삭제합니다.
            </p>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
